const fs = require('fs');
const path = require('path');
const { PNG } = require('pngjs');

/**
 * The native splash image is generated by scripts/generate-splash-icon.js. The opening animation draws nothing at
 * t = 0 and the splash and the JS loading screen share the ink ground, so the splash image is fully transparent:
 * the first screen is plain ink and the hand-over has nothing to jump.
 */
describe('the native splash image', () => {
  const png = PNG.sync.read(fs.readFileSync(path.join(__dirname, '../assets/splash-icon.png')));

  it('keeps the 4x mark canvas the splash config sizes against', () => {
    expect([png.width, png.height]).toEqual([384, 448]);
  });

  it('is fully transparent: no pixel of it is ever drawn over the ink ground', () => {
    let opaque = 0;
    for (let i = 3; i < png.data.length; i += 4) if (png.data[i] !== 0) opaque += 1;
    expect(opaque).toBe(0);
  });
});
